import{_ as t,c as a,o as e,a3 as p}from"./chunks/framework.C5U8cnJv.js";const i="/xhh-blog/assets/image-7.BQnaoqKe.png",r="/xhh-blog/assets/image-10.rHlYoq15.png",o="/xhh-blog/assets/image-11.Ce-RbATs.png",l="/xhh-blog/assets/image-3.b1-8UuXE.png",n="/xhh-blog/assets/image-2.Cl8AS1HH.png",d="/xhh-blog/assets/image-5.DTAbKJm2.png",s="/xhh-blog/assets/image-4.CI8Apfey.png",h="/xhh-blog/assets/image-1.CC71Ogak.png",u="/xhh-blog/assets/image.Dp4VGbyC.png",c="/xhh-blog/assets/image-6.BJ4JwYvb.png",g="/xhh-blog/assets/image-8.BhcuSdFG.png",m="/xhh-blog/assets/image-9.DntF6TtF.png",O=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"technology/uni-app/uni-app.md","filePath":"technology/uni-app/uni-app.md"}'),b={name:"technology/uni-app/uni-app.md"},x=p('<h2 id="相关文档" tabindex="-1">相关文档 <a class="header-anchor" href="#相关文档" aria-label="Permalink to &quot;相关文档&quot;">​</a></h2><ul><li><a href="https://uniapp.dcloud.net.cn/" target="_blank" rel="noreferrer">uni-app</a></li><li><a href="https://doc.dcloud.net.cn/uni-app-x/" target="_blank" rel="noreferrer">uni-app x</a></li><li><a href="https://www.dcloud.io/hbuilderx.html" target="_blank" rel="noreferrer">HbuilderX</a></li><li><a href="https://dev.dcloud.net.cn/pages/app/list" target="_blank" rel="noreferrer">开发者后台</a></li></ul><h2 id="新建项目" tabindex="-1">新建项目 <a class="header-anchor" href="#新建项目" aria-label="Permalink to &quot;新建项目&quot;">​</a></h2><p><img src="'+i+'" alt="alt text"></p><h3 id="uni-app-和-uni-app-x-区别" tabindex="-1">uni-app 和 uni-app X 区别： <a class="header-anchor" href="#uni-app-和-uni-app-x-区别" aria-label="Permalink to &quot;uni-app 和 uni-app X 区别：&quot;">​</a></h3><ul><li><strong>uni-app（老版）</strong></li></ul><p>App 端：WebView(.vue)/Weex(.nvue) 渲染，JS 代码跑在 V8/JSC 引擎，靠<strong>JSBridge</strong>和原生通信，属于 Web 套壳 App； 页面文件：<code>.vue</code>，Vue2/Vue3 都支持；</p><ul><li><strong>uni-app X（新版）</strong></li></ul><p>App 端：<strong>UVue 原生渲染</strong>，无 JS 引擎，逻辑用<strong>UTS 强类型语言</strong>直接编译成 Kotlin（Android）、Swift（iOS）、ArkTS（鸿蒙），真正原生 App； 页面文件：<code>.uvue</code>后缀，仅兼容Vue3； 禁用 plus.xxx，全部 uni.xxx；</p><hr><table tabindex="0"><thead><tr><th>判断点</th><th>传统 uni-app（老版）</th><th>uni-app X</th></tr></thead><tbody><tr><td>manifest.json</td><td>无 <code>uni-app-x</code> 字段</td><td>顶层有 <code>&quot;uni-app-x&quot;:{}</code></td></tr><tr><td>文件后缀</td><td><code>.vue</code>、可能有<code>.nvue</code></td><td><code>.uvue</code>，无nvue；脚本会出现 <code>&lt;script lang=&quot;uts&quot;&gt;</code></td></tr><tr><td>plus API</td><td>App端大量使用<code>plus.xxx</code></td><td>完全禁用plus</td></tr><tr><td>条件编译</td><td><code>#ifdef APP-PLUS</code> 注释宏</td><td>运行时平台判断 <code>uni.getSystemInfoSync()</code></td></tr><tr><td>页面语法</td><td>Vue2/Vue3双支持，文字可不套text</td><td>仅Vue3 setup，文字必须<code>&lt;text&gt;</code>包裹</td></tr><tr><td>原生调用</td><td>plus模块 / 5+Runtime</td><td>UTSAndroid/UTSiOS 直接调系统</td></tr><tr><td>新建页面</td><td>默认新建 <code>.vue</code>，可选<code>.nvue</code></td><td>默认新建 <code>.uvue</code></td></tr></tbody></table><h3 id="新建-uni-app-项目和-5-app-项目区别" tabindex="-1">新建 uni-app 项目和 5+App 项目区别： <a class="header-anchor" href="#新建-uni-app-项目和-5-app-项目区别" aria-label="Permalink to &quot;新建 uni-app 项目和 5+App 项目区别：&quot;">​</a></h3><ul><li>技术栈‌：uni-app 强制使用 ‌Vue.js；5+App 使用传统 ‌HTML+CSS+JS‌ (.html 入口)。</li><li>API 调用‌：uni-app 主用 uni.xxx 通用 API（底层兼容 5+）；5+App 直接调用 plus.xxx 原生 API。</li><li>跨端能力‌：uni-app 一套代码编译至 ‌iOS/Android/H5/多端小程序‌；5+App ‌仅能打包为 App‌。</li></ul><h2 id="项目构建配置" tabindex="-1">项目构建配置 <a class="header-anchor" href="#项目构建配置" aria-label="Permalink to &quot;项目构建配置&quot;">​</a></h2><p><code>manifest.json</code></p><p><img src="'+r+'" alt="alt text"></p><h2 id="插件" tabindex="-1">插件 <a class="header-anchor" href="#插件" aria-label="Permalink to &quot;插件&quot;">​</a></h2><p>1.菜单 =&gt; 工具 =&gt; 插件安装</p><p>安装的是【HBuilderX 编辑器本身】的插件，作用于整个软件，所有项目生效</p><p>2.插件市场</p><p><img src="'+o+'" alt="alt text"></p><p>会导入到 uni_modules 中</p><h2 id="运行" tabindex="-1">运行 <a class="header-anchor" href="#运行" aria-label="Permalink to &quot;运行&quot;">​</a></h2><h3 id="运行到浏览器" tabindex="-1">运行到浏览器 <a class="header-anchor" href="#运行到浏览器" aria-label="Permalink to &quot;运行到浏览器&quot;">​</a></h3><p>运行 - 运行到浏览器</p><h3 id="运行到微信小程序" tabindex="-1">运行到微信小程序 <a class="header-anchor" href="#运行到微信小程序" aria-label="Permalink to &quot;运行到微信小程序&quot;">​</a></h3><p>运行 - 运行到小程序模拟器 - 微信开发者工具</p><h3 id="运行到android模拟器" tabindex="-1">运行到Android模拟器 <a class="header-anchor" href="#运行到android模拟器" aria-label="Permalink to &quot;运行到Android模拟器&quot;">​</a></h3><ol><li><p>下载Android Studio</p></li><li><p>创建模拟器 (Virtual Device Manager)，运行模拟器</p></li></ol><p><img src="'+l+'" alt="alt text"></p><ol start="3"><li>HBuilderX - 运行 - 运行到手机或模拟器 - 运行到Android App基座（先安装App真机运行插件，才有这个选项）</li></ol><p><img src="'+n+'" alt="alt text"></p><h3 id="运行到android真机" tabindex="-1">运行到Android真机 <a class="header-anchor" href="#运行到android真机" aria-label="Permalink to &quot;运行到Android真机&quot;">​</a></h3><p><a href="https://uniapp.dcloud.net.cn/tutorial/run/run-app.html" target="_blank" rel="noreferrer">https://uniapp.dcloud.net.cn/tutorial/run/run-app.html</a></p><p>制作自定义调试基座 =&gt; 运行到Android App基座</p><h3 id="运行到ios模拟器" tabindex="-1">运行到iOS模拟器 <a class="header-anchor" href="#运行到ios模拟器" aria-label="Permalink to &quot;运行到iOS模拟器&quot;">​</a></h3><p><a href="https://uniapp.dcloud.net.cn/tutorial/run/installSimulator.html#ios" target="_blank" rel="noreferrer">https://uniapp.dcloud.net.cn/tutorial/run/installSimulator.html#ios</a></p><h3 id="运行到ios真机" tabindex="-1">运行到iOS真机 <a class="header-anchor" href="#运行到ios真机" aria-label="Permalink to &quot;运行到iOS真机&quot;">​</a></h3><ol><li><p>安装itunes连接真机</p></li><li><p>制作自定义基座</p></li></ol><p>运行 - 运行到手机或模拟器 - 制作自定义调试基座 - 选择iOS(ipa包)</p><p><img src="'+d+'" alt="alt text"></p><ol start="3"><li>HBuilderX - 运行 - 运行到手机或模拟器 - 运行到iOS App基座</li></ol><p><img src="'+s+'" alt="alt text"></p><p>选中上一步骤生成的基座。</p><h2 id="发行" tabindex="-1">发行 <a class="header-anchor" href="#发行" aria-label="Permalink to &quot;发行&quot;">​</a></h2><h3 id="发布为h5" tabindex="-1">发布为h5 <a class="header-anchor" href="#发布为h5" aria-label="Permalink to &quot;发布为h5&quot;">​</a></h3><p>发行 - 网站-PC Web或 手机 H5 打包文件目录：unpackage\\dist\\build\\web</p><h3 id="发布微信小程序" tabindex="-1">发布微信小程序 <a class="header-anchor" href="#发布微信小程序" aria-label="Permalink to &quot;发布微信小程序&quot;">​</a></h3><ol><li><p>配置微信开发者工具路径（工具-设置）</p><p><img src="'+h+'" alt="alt text"></p></li><li><p>微信小程序开启服务端口</p><p><img src="'+u+'" alt="alt text"></p></li><li><p>(HBuilderX)mainfest.json -&gt; 微信小程序配置 -&gt; 填写AppId</p></li><li><p>(HBuilderX)发行 - 小程序-微信</p></li><li><p>微信开发者工具 “上传”</p></li></ol><h3 id="android云打包" tabindex="-1">Android云打包 <a class="header-anchor" href="#android云打包" aria-label="Permalink to &quot;Android云打包&quot;">​</a></h3><p>发行 =&gt; 原生App云打包</p><p>使用云端证书：</p><p><img src="'+c+'" alt="alt text"></p><p>使用自有证书(DCLOUD开发者后台)：</p><p><img src="'+g+'" alt="alt text"></p><h3 id="ios云打包" tabindex="-1">iOS云打包 <a class="header-anchor" href="#ios云打包" aria-label="Permalink to &quot;iOS云打包&quot;">​</a></h3><p>申请ios证书教程：<a href="https://ask.dcloud.net.cn/article/152" target="_blank" rel="noreferrer">https://ask.dcloud.net.cn/article/152</a></p><p><img src="'+m+'" alt="alt text"></p><p>Apple开发者后台(证书、描述文件、设备 UDID 管理): <a href="https://developer.apple.com/account/" target="_blank" rel="noreferrer">https://developer.apple.com/account/</a></p><p>苹果上架后台：<a href="https://appstoreconnect.apple.com/" target="_blank" rel="noreferrer">https://appstoreconnect.apple.com/</a></p>',60),_=[x];function f(A,q,S,k,P,v){return e(),a("div",null,_)}const T=t(b,[["render",f]]);export{O as __pageData,T as default};
